   118	// Group events by day, and group same-title events together within each day
   119	function groupEventsByDay(events) {
   120	  const dayGroups = {};
   121	  
   122	  // First group by date
   123	  events.forEach(event => {
   124	    if (!event.date) return;
   125	    
   126	    if (!dayGroups[event.date]) {
   127	      dayGroups[event.date] = [];
   128	    }
   129	    dayGroups[event.date].push(event);
   130	  });
   131	  
   132	  // For each day, group events by title
   133	  Object.keys(dayGroups).forEach(date => {
   134	    const dayEvents = dayGroups[date];
   135	    const titleGroups = {};
   136	    
   137	    dayEvents.forEach(event => {
   138	      const title = event.title || '';
   139	      if (!titleGroups[title]) {
   140	        titleGroups[title] = [];
   141	      }
   142	      titleGroups[title].push(event);
   143	    });
   144	    
   145	    // Sort events within each title group by time
   146	    Object.keys(titleGroups).forEach(title => {
   147	      titleGroups[title].sort((a, b) => {
   148	        if (!a.time && !b.time) return 0;
   149	        if (!a.time) return 1;
   150	        if (!b.time) return -1;
   151	        return a.time.localeCompare(b.time);
   152	      });
   153	    });
   154	    
   155	    // Replace the day's events with grouped events
   156	    dayGroups[date] = Object.keys(titleGroups).map(title => ({
   157	      isGrouped: true,
   158	      title: title,
   159	      events: titleGroups[title],
   160	      category: titleGroups[title][0].category,
   161	      venue: titleGroups[title][0].venue,
   162	      area: titleGroups[title][0].area,
   163	      date: date,
   164	    }));
   165	    
   166	    // Sort grouped events by first event's time
   167	    dayGroups[date].sort((a, b) => {
   168	      const aTime = a.events[0]?.time || '';
   169	      const bTime = b.events[0]?.time || '';
   170	      if (!aTime && !bTime) return 0;
   171	      if (!aTime) return 1;
   172	      if (!bTime) return -1;
   173	      return aTime.localeCompare(bTime);
   174	    });
   175	  });
   176	  
   177	  // Convert to array and sort by date
   178	  const result = Object.keys(dayGroups)
   179	    .sort((a, b) => a.localeCompare(b))
   180	    .map(date => ({
   181	      date,
   182	      title: formatDayHeader(date),
   183	      events: dayGroups[date],
   184	    }));
   185	  
   186	  return result;
